INDEX = json.loads(INDEX_JSON)


def _s(v): return isinstance(v, str) and v.strip() != ""
def _id(v): return isinstance(v, str) and L._full(L.ID_RE, v)


def _parse_at(s):
    i = s.find("@")
    return (s, None) if i < 0 else (s[:i], s[i + 1:])


def _type_msg(types, t): return "needs " + " or ".join(types) + ", not " + t


def _check_ref(v, p, types, I, E):
    if not _id(v): return False
    t = I["types"].get(v)
    if not t:
        E("unknown-structure", p, NOT_KNOWN); return False
    if types != "*" and t not in types:
        E("wrong-type", p, _type_msg(types, t)); return False
    return True


def _check_to(rel, v, p, I, E):
    want = I["rel"][rel]["to"]
    if not _s(v): return
    if want == "dof":
        parts = v.split(".")
        j = parts[0]; d = parts[1] if len(parts) > 1 else None
        if j not in I["dofs"] or d not in I["dofs"][j] or len(parts) != 2: E("unknown-dof", p, "not a movement (joint.dof) of anatomy@1")
        return
    if isinstance(want, str) and want.startswith("word:"):
        ws = want[5:].split("|")
        if v not in ws: E("enum", p, "one of " + ", ".join(ws))
        return
    if not _id(v):
        E("value", p, L.kind_msg("id")); return
    _check_ref(v, p, want, I, E)


def _is_finding(name, I):
    i = name.find(".")
    if i < 0: return False
    g, k = name[:i], name[i + 1:]
    G = {"muscle": I["muscles"], "loss": I["muscles"], "move": I["movers"], "reflex": I["reflexes"], "area": I["areas"], "fn": I["fns"],
         "dermatome": I["dermatomes"], "sign": I["signs"], "nerve": I["nerves"]}
    return g in G and k in G[g]


def _js_int(v): return L.is_num(v) and float(v).is_integer()


def _self_crossing(v):
    n = len(v) // 2
    if n < 4: return False
    def P(i): i %= n; return (v[2 * i], v[2 * i + 1])
    def sign(x): return (x > 0) - (x < 0)
    def orient(a, b, c): return sign((b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]))
    for i in range(n):
        for j in range(i + 2, n):
            if i == 0 and j == n - 1: continue
            a, b, c, d = P(i), P(i + 1), P(j), P(j + 1)
            if orient(a, b, c) * orient(a, b, d) < 0 and orient(c, d, a) * orient(c, d, b) < 0: return True
    return False


def _extra(mode, m, I, E, W):
    vs = m.get("variants")
    if isinstance(vs, list):
        for i, v in enumerate(vs):
            p = f"model.variants[{i}]"
            if not _id(v): continue
            if v not in I["variants"]: E("unknown-variant", p, "not a known variant")
            elif I["variants"][v] != mode: W("variant-unused", p, f"has no effect in {mode} mode")
        if "left-dominance" in vs and "codominance" in vs: E("inconsistent", "model.variants", "left-dominance and codominance exclude each other")
        if "prefixed-plexus" in vs and "postfixed-plexus" in vs: E("inconsistent", "model.variants", "prefixed-plexus and postfixed-plexus exclude each other")
    if isinstance(m.get("labels"), list):
        for i, l in enumerate(m["labels"]):
            if isinstance(l, dict): _check_ref(l.get("id"), f"model.labels[{i}].id", "*", I, E)
    if mode == "lesion":
        Ls = m["lesions"] if isinstance(m.get("lesions"), list) else []
        for i, les in enumerate(Ls):
            if not isinstance(les, dict) or not isinstance(les.get("at"), list): continue
            any_root = False
            for j, s in enumerate(les["at"]):
                p = f"model.lesions[{i}].at[{j}]"
                if not _s(s): continue
                sid, level = _parse_at(s)
                if not _id(sid):
                    E("value", p, "needs a structure id, or id@level for a nerve"); continue
                t = I["types"].get(sid)
                if not t:
                    E("unknown-structure", p, NOT_KNOWN); continue
                if t not in I["lesionable"]:
                    E("wrong-type", p, f"a {t} is not a lesion site (a root, a trunk, a division, a cord, a nerve or a site)"); continue
                if t == "root": any_root = True
                if level is not None:
                    if t != "nerve": E("unknown-level", p, "only a nerve has levels")
                    elif level not in I["levels"][sid]: E("unknown-level", p, f"{sid} has no level \"{level}\" (one of {', '.join(I['levels'][sid])})")
            if les.get("avulsion") is True and not any_root: W("inconsistent", f"model.lesions[{i}].avulsion", "only a root can be avulsed")
        n = len(Ls)
        for k in ("pick", "compare"):
            v = m.get(k)
            if L.is_num(v) and (not _js_int(v) or v < 0 or v >= n): E("value", "model." + k, f"needs an index of model.lesions (0 to {n - 1})")
        if isinstance(m.get("findings"), list):
            for i, f in enumerate(m["findings"]):
                if _s(f) and not _is_finding(f, I): E("unknown-finding", f"model.findings[{i}]", "not a finding of lesion mode (muscle., move., reflex., area., fn., dermatome., sign., nerve.)")
    elif mode == "query":
        ids = set()
        if isinstance(m.get("facts"), list):
            for i, f in enumerate(m["facts"]):
                if not isinstance(f, dict): continue
                p = f"model.facts[{i}]"
                if isinstance(f.get("id"), str):
                    if f["id"] in ids: E("value", p + ".id", "duplicate id")
                    ids.add(f["id"])
                if not isinstance(f.get("rel"), str) or f["rel"] not in I["rel"]: continue
                _check_ref(f.get("from"), p + ".from", I["rel"][f["rel"]]["from"], I, E)
                _check_to(f["rel"], f.get("to"), p + ".to", I, E)
        q = m.get("quiz")
        if isinstance(q, dict) and isinstance(q.get("rel"), str) and q["rel"] in I["rel"]:
            hf, ht = _s(q.get("from")), _s(q.get("to"))
            if hf == ht: E("inconsistent", "model.quiz", "needs from or to (one of them): the choices fill the other")
            else:
                rel = q["rel"]
                if hf: _check_ref(q["from"], "model.quiz.from", I["rel"][rel]["from"], I, E)
                else: _check_to(rel, q["to"], "model.quiz.to", I, E)
                ch = q.get("choices")
                if isinstance(ch, list):
                    for i, c in enumerate(ch):
                        p = f"model.quiz.choices[{i}]"
                        if not _s(c): continue
                        if hf: _check_to(rel, c, p, I, E)
                        else: _check_ref(c, p, I["rel"][rel]["from"], I, E)
                pk = q.get("pick")
                if L.is_num(pk) and isinstance(ch, list) and (not _js_int(pk) or pk < 0 or pk >= len(ch)): E("value", "model.quiz.pick", f"needs an index of model.quiz.choices (0 to {len(ch) - 1})")
        if "of" in m: _check_ref(m["of"], "model.of", "*", I, E)
    elif mode == "trace":
        sysname = m.get("system") or "blood"
        T = {"blood": ["artery", "vein", "heart", "bed"], "fetal": ["artery", "vein", "heart", "bed"], "lymph": ["lymph", "vein"],
             "nerve": ["root", "trunk", "division", "cord", "nerve", "muscle", "area", "function"]}.get(sysname, []) if isinstance(sysname, str) else []
        okf = _check_ref(m.get("from"), "model.from", T, I, E)
        okt = _check_ref(m.get("to"), "model.to", T, I, E)
        if okf and okt and m["from"] == m["to"]: E("inconsistent", "model.to", "is the same as model.from")
        if isinstance(m.get("via"), list):
            for i, v in enumerate(m["via"]): _check_ref(v, f"model.via[{i}]", T, I, E)
        if isinstance(m.get("avoid"), list):
            for i, v in enumerate(m["avoid"]):
                if _check_ref(v, f"model.avoid[{i}]", T, I, E) and (v == m.get("from") or v == m.get("to")): E("inconsistent", f"model.avoid[{i}]", "blocks the start or the end")
    elif mode == "rom":
        hj, hd = "joint" in m, "dof" in m
        if hj != hd: E("value", "model.joint" if not hj else "model.dof", "missing")
        elif hj and _check_ref(m["joint"], "model.joint", ["joint"], I, E) and isinstance(m["dof"], str):
            src = m.get("source")
            if m["dof"] not in I["dofs"][m["joint"]]: E("unknown-dof", "model.dof", f"{m['joint']} has no movement \"{m['dof']}\"")
            elif (src is None or (isinstance(src, str) and src in I["rom"])) and (m["joint"] + "." + m["dof"]) not in I["rom"][src or "aaos"]:
                E("no-rom", "model.dof", f"the {src or 'aaos'} table has no value for {m['joint']}.{m['dof']}")
        if not hj and "beighton" not in m: E("value", "model", "needs joint and dof, or beighton")
    elif mode == "biomech":
        if not any(k in m for k in ("lever", "hip", "niosh", "segment", "arm")): E("value", "model", "needs lever, hip, niosh, segment or arm")
    elif mode == "regions":
        img = m.get("image")
        img = img if isinstance(img, list) and len(img) == 2 and all(L.is_num(x) for x in img) else None
        R = m["regions"] if isinstance(m.get("regions"), list) else []
        for i, r in enumerate(R):
            if not isinstance(r, dict): continue
            p = f"model.regions[{i}]"
            _check_ref(r.get("structure"), p + ".structure", "*", I, E)
            shapes = [k for k in ("polygon", "polyline", "circle") if k in r]
            if len(shapes) != 1:
                E("region", p, "needs one of polygon, polyline, circle"); continue
            k = shapes[0]; v = r[k]
            if not isinstance(v, list) or not all(L.is_num(x) for x in v): continue
            if k == "polygon" and (len(v) < 6 or len(v) % 2):
                E("region", p + ".polygon", "needs at least 3 x, y pairs"); continue
            if k == "polyline" and (len(v) < 4 or len(v) % 2):
                E("region", p + ".polyline", "needs at least 2 x, y pairs"); continue
            if k == "polyline" and "width" not in r: E("region", p + ".width", "missing (the stroke width of a polyline, in pixels)")
            pts = [v[0] - v[2], v[1] - v[2], v[0] + v[2], v[1] + v[2]] if k == "circle" else v
            if img and any(x < 0 or x > img[j % 2] for j, x in enumerate(pts)): E("region", p + "." + k, "outside the image")
            if k == "circle" and not (v[2] > 0): E("region", p + ".circle", "needs a radius > 0")
            if k == "polygon" and _self_crossing(v): E("region", p + ".polygon", "crosses itself")
        if "target" in m and _check_ref(m["target"], "model.target", "*", I, E) and not any(isinstance(r, dict) and r.get("structure") == m["target"] for r in R):
            W("inconsistent", "model.target", "no region shows this structure itself")


def _output_known(mode, o, m, I):
    of = o["of"]; O = I["outs"][mode]
    if o["kind"] != "scalar": return of in O[o["kind"]]
    if of in O["scalar"]: return True
    if of.startswith("issue."): return of[6:] in I["issues"][mode]
    if mode == "lesion": return _is_finding(of[8:], I) if of.startswith("differs.") else _is_finding(of, I)
    if mode == "query":
        if of.startswith("fact."): return isinstance(m.get("facts"), list) and any(isinstance(f, dict) and f.get("id") == of[5:] for f in m["facts"])
        if of.startswith("root."): return of[5:] in I["segs"]
        return False
    if mode == "trace": return (of.startswith("via.") and of[4:] in I["types"]) or (of.startswith("pos.") and of[4:] in I["types"])
    return False


def check_spec(spec):
    P, E, W = L.problems()
    m = spec.get("model") if isinstance(spec, dict) else None
    kinds = ["scalar", "series", "scene"]
    if not isinstance(m, dict):
        E("format", "model", "not an object"); L.check_outputs(spec, ID, kinds, lambda o, at, E, W: None, E, W); return P
    I = INDEX
    mode = m.get("mode") if isinstance(m.get("mode"), str) and m.get("mode") in I["modes"] else None
    T = dict(I["schema"]["common"])
    if mode: T.update(I["schema"][mode])
    L.walk(m, T, "model", E, W)
    if mode: _extra(mode, m, I, E, W)

    def out(o, at, E, W):
        if mode and not _output_known(mode, o, m, I): E("output", at + ".of", f"{mode} computes no {o['kind']} \"{o['of']}\"")
    L.check_outputs(spec, ID, kinds, out, E, W)
    return P


def exprs(spec):
    out = []
    m = spec.get("model") if isinstance(spec, dict) else None
    if not isinstance(m, dict) or m.get("mode") not in INDEX["modes"]: return out

    def visit(v, kd, p):
        if v is None or kd is None: return
        if isinstance(kd, str):
            if kd.replace("!", "") == "numx" and isinstance(v, str): out.append((v, p, []))
            return
        if "$obj" in kd:
            if isinstance(v, dict):
                for k in kd["$obj"]: visit(v.get(k), kd["$obj"][k], p + "." + k)
            return
        if "$list" in kd and isinstance(v, list):
            for i, x in enumerate(v): visit(x, kd["$list"], f"{p}[{i}]")
    T = INDEX["schema"][m["mode"]]
    for k in T: visit(m.get(k), T[k], "model." + k)
    return out


def keys(spec):
    m = spec.get("model") if isinstance(spec, dict) else None
    out = []
    if isinstance(m, dict) and isinstance(m.get("labels"), list):
        for i, l in enumerate(m["labels"]):
            if isinstance(l, dict) and isinstance(l.get("key"), str): out.append((l["key"], f"model.labels[{i}].key"))
    return out
